-- Additive catalogue: never updates legacy definitions or user progress.
-- CATALOG_REQUIREMENT is a non-counting placeholder, not a measurement.
BEGIN;
ALTER TABLE achievements DROP CONSTRAINT IF EXISTS achievements_metric_check;
ALTER TABLE achievements ADD CONSTRAINT achievements_metric_check CHECK
  (metric IN ('TRANSLATIONS_COMPLETED', 'SIGNS_LEARNED', 'ALPHABET_COMPLETED', 'SESSIONS_COMPLETED', 'CATALOG_REQUIREMENT'));
ALTER TABLE achievements
  ADD COLUMN IF NOT EXISTS collection VARCHAR(10) NOT NULL DEFAULT 'legacy' CHECK (collection IN ('legacy', 'catalog')),
  ADD COLUMN IF NOT EXISTS availability VARCHAR(12) NOT NULL DEFAULT 'available' CHECK (availability IN ('available', 'upcoming')),
  ADD COLUMN IF NOT EXISTS category VARCHAR(15) CHECK (category IN ('translation','practice','vocabulary','consistency','community')),
  ADD COLUMN IF NOT EXISTS level VARCHAR(6) CHECK (level IN ('bronze','silver','gold')),
  ADD COLUMN IF NOT EXISTS display_order INTEGER NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS localizations JSONB NOT NULL DEFAULT '{}';
ALTER TABLE achievements DROP CONSTRAINT IF EXISTS ck_achievement_catalog_metadata;
ALTER TABLE achievements ADD CONSTRAINT ck_achievement_catalog_metadata CHECK (
  (collection = 'legacy' AND availability = 'available') OR
  (collection = 'catalog' AND category IS NOT NULL AND level IS NOT NULL)
);
ALTER TABLE achievements DROP CONSTRAINT IF EXISTS ck_achievement_unmeasured;
ALTER TABLE achievements ADD CONSTRAINT ck_achievement_unmeasured
  CHECK (metric <> 'CATALOG_REQUIREMENT' OR availability = 'upcoming');
ALTER TABLE achievements DROP CONSTRAINT IF EXISTS ck_achievement_legacy_publication;
ALTER TABLE achievements ADD CONSTRAINT ck_achievement_legacy_publication
  CHECK (collection <> 'catalog' OR is_active = FALSE);
-- is_active=FALSE keeps all new definitions invisible to the unmodified v1 backend.
-- v2 explicitly publishes collection='catalog'; availability still controls measurement.
-- target_count=1 below is only the storage sentinel for a compound requirement.
-- The API exposes targetCount/currentCount=null for upcoming entries. It is NOT a progress target.
